<script setup>
import { computed } from 'vue'
import { Head, useForm } from '@inertiajs/vue3'
import AdminLayout from '../../../Layouts/AdminLayout.vue'
import PageHeader from '../../../Components/Ui/PageHeader.vue'
import AccountingNav from '../../../Components/Accounting/AccountingNav.vue'
import AccountingPanel from '../../../Components/Accounting/AccountingPanel.vue'
defineOptions({layout:AdminLayout})
const props=defineProps({defaults:Object,currencies:Array,paymentMethods:Array,suppliers:Array,hasBranch:Boolean,urls:Object});const form=useForm({asset_number:props.defaults.assetNumber,name:'',category:'',description:'',vendor_name:'',supplier_id:'',acquisition_date:props.defaults.acquisitionDate,in_service_date:props.defaults.inServiceDate,foreign_cost:'',foreign_salvage_value:0,currency_code:props.defaults.currencyCode,exchange_rate:props.defaults.exchangeRate,useful_life_months:props.defaults.usefulLifeMonths,payment_method:props.defaults.paymentMethod,notes:''});const selectedCurrency=computed(()=>props.currencies.find(c=>c.code===form.currency_code));const baseCost=computed(()=>Number(form.foreign_cost||0)*Number(form.exchange_rate||0));const monthly=computed(()=>Math.max(0,(baseCost.value-Number(form.foreign_salvage_value||0)*Number(form.exchange_rate||0))/Number(form.useful_life_months||1)));function currencyChanged(){form.exchange_rate=selectedCurrency.value?.base?1:(selectedCurrency.value?.rate||'')}const submit=()=>form.post(props.urls.store)
</script>
<template><Head title="إضافة أصل ثابت"/><PageHeader title="إضافة أصل ثابت" icon="bi-plus-circle-fill" subtitle="أثبت الأصل مرة واحدة؛ قيد الشراء والإهلاك اللاحق ينشئهما النظام"/><AccountingNav :urls="urls" active="fixedAssets"/><section v-if="!hasBranch" class="warning"><i class="bi bi-shop"></i><div><strong>اختر فرعاً قبل الإضافة</strong><small>الأصل وقيد شرائه يجب أن يرتبطا بفرع محدد.</small></div></section><form class="asset-form" @submit.prevent="submit"><fieldset :disabled="!hasBranch||form.processing"><div class="form-layout"><main><AccountingPanel title="هوية الأصل" description="اسم واضح ورقم يمكن لصقه على الأصل داخل المطعم." icon="bi-upc-scan"><div class="grid identity"><label><span>رقم الأصل</span><input v-model="form.asset_number" class="form-control" maxlength="40"></label><label class="wide"><span>اسم الأصل *</span><input v-model="form.name" class="form-control" placeholder="فرن بيتزا، ثلاجة، طاولة تحضير" required></label><label><span>الفئة</span><input v-model="form.category" class="form-control" placeholder="معدات، أثاث، أجهزة"></label><label><span>المورد</span><select v-model="form.supplier_id" class="form-select"><option value="">بدون ربط مورد</option><option v-for="supplier in suppliers" :key="supplier.id" :value="supplier.id">{{supplier.name}}</option></select></label><label><span>اسم بائع آخر</span><input v-model="form.vendor_name" class="form-control"></label><label class="wide"><span>وصف مختصر</span><input v-model="form.description" class="form-control"></label></div></AccountingPanel><AccountingPanel title="الشراء والقيمة" description="العملة الأصلية وسعر الصرف يوم الشراء." icon="bi-cash-stack"><div class="grid values"><label><span>تاريخ الشراء *</span><input v-model="form.acquisition_date" type="date" class="form-control" required></label><label><span>طريقة الدفع *</span><select v-model="form.payment_method" class="form-select" required><option v-for="method in paymentMethods" :key="method.code" :value="method.code">{{method.label}}</option></select></label><label><span>العملة *</span><select v-model="form.currency_code" class="form-select" required @change="currencyChanged"><option v-for="currency in currencies" :key="currency.code" :value="currency.code">{{currency.code}} — {{currency.name}}</option></select></label><label><span>سعر الصرف *</span><input v-model="form.exchange_rate" type="number" step=".00000001" min=".00000001" class="form-control" :readonly="selectedCurrency?.base" required></label><label><span>تكلفة الأصل *</span><input v-model="form.foreign_cost" type="number" step=".01" min=".01" class="form-control" required></label><label><span>القيمة التخريدية</span><input v-model="form.foreign_salvage_value" type="number" step=".01" min="0" class="form-control"></label></div></AccountingPanel><AccountingPanel title="الاستخدام والإهلاك" description="القسط الشهري يُحسب بخط مستقيم حتى القيمة التخريدية." icon="bi-graph-down-arrow" tone="amber"><div class="grid use"><label><span>تاريخ بدء الاستخدام *</span><input v-model="form.in_service_date" type="date" :min="form.acquisition_date" class="form-control" required></label><label><span>العمر الإنتاجي بالأشهر *</span><input v-model="form.useful_life_months" type="number" min="1" max="600" class="form-control" required></label><label class="wide"><span>ملاحظات</span><textarea v-model="form.notes" rows="2" class="form-control"></textarea></label></div></AccountingPanel></main><aside><section class="preview"><span><i class="bi bi-calculator"></i></span><small>التكلفة بالعملة الأساسية</small><strong>{{baseCost.toFixed(2)}}</strong><hr><small>إهلاك شهري تقريبي</small><strong>{{monthly.toFixed(2)}}</strong><p>يبدأ الإهلاك من تاريخ بدء الاستخدام، ولا يُرحّل الشهر مرتين.</p></section><div v-if="Object.keys(form.errors).length" class="errors"><strong>راجع الحقول</strong><small v-for="(error,key) in form.errors" :key="key">{{error}}</small></div></aside></div><footer><a :href="urls.index" class="btn btn-light">إلغاء</a><button class="btn btn-primary"><i class="bi bi-journal-check"></i> حفظ وترحيل قيد الشراء</button></footer></fieldset></form></template>
<style scoped>.warning{display:flex;gap:9px;margin-bottom:10px;padding:11px 13px;border:1px solid #e3c27f;border-radius:13px;color:#915500;background:#fff5e4}.warning div{display:grid}.warning strong{font-size:.72rem}.warning small{font-size:.61rem}.asset-form fieldset{border:0}.form-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;align-items:start;gap:11px}.form-layout main{display:grid;gap:10px}.form-layout aside{position:sticky;top:183px;display:grid;gap:9px}.grid{display:grid;gap:9px}.grid.identity{grid-template-columns:1fr 2fr 1fr}.grid.values{grid-template-columns:repeat(3,1fr)}.grid.use{grid-template-columns:1fr 1fr}.grid label{display:grid;gap:4px}.grid label>span{font-size:.61rem;font-weight:850}.grid .wide{grid-column:span 2}.preview{display:grid;justify-items:center;padding:17px;border:1px solid #acd2b7;border-radius:15px;color:#1f6b50;background:#eff8f2;text-align:center}.preview>span{display:grid;width:42px;height:42px;place-items:center;border-radius:12px;color:#fff;background:#1f6b50}.preview small{margin-top:9px;font-size:.58rem}.preview strong{font-size:1rem}.preview hr{width:100%;margin:10px 0 0;border-color:#cfe1d5}.preview p{margin:11px 0 0;color:#6d7c72;font-size:.59rem;line-height:1.6}.errors{display:grid;padding:11px;border-radius:11px;color:#ad2929;background:#fff0f0}.errors strong{font-size:.68rem}.errors small{font-size:.57rem}.asset-form footer{display:flex;justify-content:flex-end;gap:7px;margin-top:10px;padding:11px;border:1px solid #dfe7e2;border-radius:12px;background:#fff}@media(max-width:900px){.form-layout{grid-template-columns:1fr}.form-layout aside{position:static;grid-template-columns:1fr 1fr}.grid.identity,.grid.values{grid-template-columns:1fr 1fr}}@media(max-width:560px){.form-layout aside,.grid.identity,.grid.values,.grid.use{grid-template-columns:1fr}.grid .wide{grid-column:auto}}</style>
